// Deterministic closed-triangle / closed-AABB surface voxelizer for the
// full official Replica mesh.  It writes raw canonical NPY arrays; the Python
// protocol records hashes and qualification evidence.
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <sstream>
#include <string>
#include <unordered_set>
#include <vector>

constexpr double TOL=1e-9;
struct V{double x,y,z;V():x(0),y(0),z(0){}V(double a,double b,double c):x(a),y(b),z(c){}V operator+(const V&o)const{return{x+o.x,y+o.y,z+o.z};}V operator-(const V&o)const{return{x-o.x,y-o.y,z-o.z};}V operator*(double s)const{return{x*s,y*s,z*s};}};
static double dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;} static V cross(V a,V b){return{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};} static double n2(V a){return dot(a,a);}
struct Box{V lo,hi;Box():lo(1e300,1e300,1e300),hi(-1e300,-1e300,-1e300){}void add(V p){lo.x=std::min(lo.x,p.x);lo.y=std::min(lo.y,p.y);lo.z=std::min(lo.z,p.z);hi.x=std::max(hi.x,p.x);hi.y=std::max(hi.y,p.y);hi.z=std::max(hi.z,p.z);}};
struct Tri{int a,b,c;};

static bool point_box(V p,V c,V h){return std::abs(p.x-c.x)<=h.x+TOL&&std::abs(p.y-c.y)<=h.y+TOL&&std::abs(p.z-c.z)<=h.z+TOL;}
static bool segment_box(V a,V b,V c,V h){V d=b-a;double t0=0,t1=1;const double av[3]={a.x,a.y,a.z},dv[3]={d.x,d.y,d.z},cv[3]={c.x,c.y,c.z},hv[3]={h.x,h.y,h.z};for(int i=0;i<3;i++){double lo=cv[i]-hv[i]-TOL,hi=cv[i]+hv[i]+TOL;if(std::abs(dv[i])<1e-18){if(av[i]<lo||av[i]>hi)return false;}else{double q0=(lo-av[i])/dv[i],q1=(hi-av[i])/dv[i];if(q0>q1)std::swap(q0,q1);t0=std::max(t0,q0);t1=std::min(t1,q1);if(t0>t1)return false;}}return true;}
// Generic SAT: box axes, triangle plane normal, and edge-cross-box axes.
static bool tri_box(V a,V b,V c,V center,V half){V p[3]={a-center,b-center,c-center};for(int k=0;k<3;k++){double mn=std::min({k==0?p[0].x:k==1?p[0].y:p[0].z,k==0?p[1].x:k==1?p[1].y:p[1].z,k==0?p[2].x:k==1?p[2].y:p[2].z});double mx=std::max({k==0?p[0].x:k==1?p[0].y:p[0].z,k==0?p[1].x:k==1?p[1].y:p[1].z,k==0?p[2].x:k==1?p[2].y:p[2].z});double hh=k==0?half.x:k==1?half.y:half.z;if(mx<-hh-TOL||mn>hh+TOL)return false;}V e[3]={p[1]-p[0],p[2]-p[1],p[0]-p[2]};V n=cross(e[0],e[1]);if(n2(n)>1e-30){double r=half.x*std::abs(n.x)+half.y*std::abs(n.y)+half.z*std::abs(n.z);if(std::abs(dot(n,p[0]))>r+TOL)return false;}V axes[3]={{1,0,0},{0,1,0},{0,0,1}};for(V ed:e)for(V ax:axes){V q=cross(ed,ax);if(n2(q)<=1e-30)continue;double q0=dot(q,p[0]),q1=dot(q,p[1]),q2=dot(q,p[2]);double mn=std::min({q0,q1,q2}),mx=std::max({q0,q1,q2});double r=half.x*std::abs(q.x)+half.y*std::abs(q.y)+half.z*std::abs(q.z);if(mx<-r-TOL||mn>r+TOL)return false;}return true;}

static void write_npy_header(std::ofstream& out,const std::string& descr,const std::vector<size_t>& shape){std::ostringstream s;s<<"{'descr': '"<<descr<<"', 'fortran_order': False, 'shape': (";for(size_t i=0;i<shape.size();i++){s<<shape[i];if(shape.size()==1||i+1<shape.size())s<<",";if(i+1<shape.size())s<<" ";}s<<"), }";std::string h=s.str();size_t pre=10;size_t pad=(16-((pre+h.size()+1)%16))%16;h.append(pad,' ');h.push_back('\n');out.write("\x93NUMPY",6);char ver[2]={1,0};out.write(ver,2);uint16_t n=(uint16_t)h.size();out.write((char*)&n,2);out.write(h.data(),h.size());}
template<class T> static void write_npy(const std::string& p,const std::string& descr,const std::vector<size_t>& shape,const std::vector<T>& a){std::ofstream o(p,std::ios::binary);if(!o)throw std::runtime_error("cannot write "+p);write_npy_header(o,descr,shape);o.write((char*)a.data(),a.size()*sizeof(T));}

static uint64_t encode(int x,int y,int z){constexpr int O=1<<20;constexpr uint64_t M=(1ULL<<21)-1;return(((uint64_t)(x+O)&M)<<42)|(((uint64_t)(y+O)&M)<<21)|((uint64_t)(z+O)&M);}static int decode(uint64_t k,int s){constexpr int O=1<<20;constexpr uint64_t M=(1ULL<<21)-1;return (int)((k>>s)&M)-O;}

int main(int argc,char**argv){if(argc!=4){std::cerr<<"usage: voxelizer mesh.ply voxel_size output_dir\n";return 2;}try{double s=std::stod(argv[2]);if(!(s>0))throw std::runtime_error("invalid voxel size");std::string root=argv[3];std::ifstream in(argv[1],std::ios::binary);if(!in)throw std::runtime_error("cannot open mesh");std::string line;size_t nv=0,nf=0;while(std::getline(in,line)){if(line.rfind("element vertex ",0)==0)nv=std::stoull(line.substr(15));else if(line.rfind("element face ",0)==0)nf=std::stoull(line.substr(13));else if(line=="end_header")break;}if(!nv||!nf)throw std::runtime_error("bad PLY header");std::vector<V> v;v.reserve(nv);Box bbox;for(size_t i=0;i<nv;i++){float x,y,z,nx,ny,nz;uint8_t r,g,b;in.read((char*)&x,4);in.read((char*)&y,4);in.read((char*)&z,4);in.read((char*)&nx,4);in.read((char*)&ny,4);in.read((char*)&nz,4);in.read((char*)&r,1);in.read((char*)&g,1);in.read((char*)&b,1);v.emplace_back(x,y,z);bbox.add(v.back());}std::vector<Tri> f;f.reserve(nf);for(size_t i=0;i<nf;i++){uint8_t n;in.read((char*)&n,1);std::vector<uint32_t> q(n);for(uint8_t j=0;j<n;j++)in.read((char*)&q[j],4);for(uint8_t j=1;j+1<n;j++)f.push_back({(int)q[0],(int)q[j],(int)q[j+1]});}
V origin={s*std::floor((bbox.lo.x-1e-9)/s),s*std::floor((bbox.lo.y-1e-9)/s),s*std::floor((bbox.lo.z-1e-9)/s)},half={s/2,s/2,s/2};std::unordered_set<uint64_t> vox;vox.reserve(f.size()/3);size_t lost=0;for(size_t ti=0;ti<f.size();ti++){auto t=f[ti];V a=v[t.a],b=v[t.b],c=v[t.c];Box tb;tb.add(a);tb.add(b);tb.add(c);int ix0=(int)std::floor((tb.lo.x-origin.x-TOL)/s),iy0=(int)std::floor((tb.lo.y-origin.y-TOL)/s),iz0=(int)std::floor((tb.lo.z-origin.z-TOL)/s),ix1=(int)std::floor((tb.hi.x-origin.x+TOL)/s),iy1=(int)std::floor((tb.hi.y-origin.y+TOL)/s),iz1=(int)std::floor((tb.hi.z-origin.z+TOL)/s);bool hit=false;double area2=n2(cross(b-a,c-a));for(int ix=ix0;ix<=ix1;ix++)for(int iy=iy0;iy<=iy1;iy++)for(int iz=iz0;iz<=iz1;iz++){V cc={origin.x+(ix+.5)*s,origin.y+(iy+.5)*s,origin.z+(iz+.5)*s};bool ok=area2>1e-24?tri_box(a,b,c,cc,half):(n2(b-a)>1e-18?segment_box(a,b,cc,half):(n2(c-a)>1e-18?segment_box(a,c,cc,half):point_box(a,cc,half)));if(ok){vox.insert(encode(ix,iy,iz));hit=true;}}if(!hit)lost++;if((ti+1)%500000==0)std::cerr<<"triangles="<<(ti+1)<<" voxels="<<vox.size()<<"\n";}std::vector<uint64_t> keys(vox.begin(),vox.end());std::sort(keys.begin(),keys.end());size_t n=keys.size();std::vector<float> means;means.reserve(3*n);std::vector<float> scales;scales.reserve(3*n);std::vector<float> quat;quat.reserve(4*n);std::vector<float> opacity;opacity.reserve(n);std::vector<float> color;color.reserve(3*n);std::vector<int64_t> indices;indices.reserve(3*n);float rad=(float)(std::sqrt(3.0)/2*s+1e-4);for(uint64_t k:keys){int ix=decode(k,42),iy=decode(k,21),iz=decode(k,0);means.push_back((float)(origin.x+(ix+.5)*s));means.push_back((float)(origin.y+(iy+.5)*s));means.push_back((float)(origin.z+(iz+.5)*s));scales.insert(scales.end(),{rad,rad,rad});quat.insert(quat.end(),{1,0,0,0});opacity.push_back(.99f);color.insert(color.end(),{.5f,.5f,.5f});indices.insert(indices.end(),{ix,iy,iz});}
write_npy(root+"/means_world_m.npy","<f4",{n,3},means);write_npy(root+"/scales_linear_m.npy","<f4",{n,3},scales);write_npy(root+"/quaternions_wxyz.npy","<f4",{n,4},quat);write_npy(root+"/opacities_probability.npy","<f4",{n},opacity);write_npy(root+"/colors_rgb.npy","<f4",{n,3},color);write_npy(root+"/voxel_indices_int64.npy","<i8",{n,3},indices);std::ofstream js(root+"/voxelizer_raw_summary.json");js<<std::setprecision(17)<<"{\n  \"voxel_size_m\": "<<s<<",\n  \"origin_m\": ["<<origin.x<<", "<<origin.y<<", "<<origin.z<<"],\n  \"source_vertex_count\": "<<v.size()<<",\n  \"source_triangle_count\": "<<f.size()<<",\n  \"source_primitive_loss\": "<<lost<<",\n  \"gaussian_count\": "<<n<<",\n  \"sphere_scale_m\": "<<rad<<"\n}\n";std::cerr<<"gaussians="<<n<<" source_primitive_loss="<<lost<<"\n";}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
